mapper.select:
SELECT DISTINCT b.block_id AS blockId, pm.user_id AS userId FROM block b JOIN step s ON s.step_id = b.step_id AND s.deleted_at IS NULL JOIN project p ON p.project_id = s.project_id AND p.deleted_at IS NULL JOIN project_member pm ON pm.project_id = p.project_id LEFT JOIN step_permission sp ON sp.step_id = s.step_id AND sp.user_id = pm.user_id JOIN employee e ON e.user_id = pm.user_id AND e.company_id = #{companyId} AND e.resigned_at IS NULL AND e.deleted_at IS NULL JOIN account ac ON ac.user_id = e.user_id AND ac.status = 'ACTIVE' AND ac.deleted_at IS NULL AND ac.role <> 'ADMIN' WHERE b.block_id IN
#{blockId}
AND b.deleted_at IS NULL AND COALESCE(sp.permission, pm.permission) = 'EDITOR' ORDER BY b.block_id, pm.user_id
